import unittest
from collections import UserDict

from solution import normalize_charge


class NormalizeChargeTests(unittest.TestCase):
    def test_positive_integer(self):
        fields = {'description': 'service fee', 'minor_units': 125}
        result = normalize_charge(fields)
        self.assertEqual(result, {'description': 'service fee', 'minor_units': 125})
        self.assertIsNot(result, fields)

    def test_ascii_digit_string_and_leading_zeroes(self):
        self.assertEqual(
            normalize_charge(UserDict({'description': 'charge', 'minor_units': '00042'})),
            {'description': 'charge', 'minor_units': 42},
        )

    def test_input_is_not_mutated(self):
        fields = {'description': 'x', 'minor_units': '007'}
        before = dict(fields)
        result = normalize_charge(fields)
        result['description'] = 'changed'
        self.assertEqual(fields, before)

    def test_invalid_minor_units(self):
        invalid = [
            True, False, 0, -1, 1.0, None, '', '0', '000', '+1', '-1',
            ' 1', '1 ', '1.0', '1e2', '１２', '١٢', '²', '1_0',
        ]
        for value in invalid:
            with self.subTest(value=value):
                with self.assertRaises(ValueError):
                    normalize_charge({'description': 'x', 'minor_units': value})

    def test_invalid_mapping_or_description(self):
        malformed = [
            None,
            [],
            {},
            {'description': 'x', 'minor_units': 1, 'extra': 2},
            {'description': '', 'minor_units': 1},
            {'description': None, 'minor_units': 1},
        ]
        for fields in malformed:
            with self.subTest(fields=fields):
                with self.assertRaises(ValueError):
                    normalize_charge(fields)


if __name__ == '__main__':
    unittest.main()

